import {
  MenuAlt1Icon,
  SearchIcon,
  BellIcon,
  UserIcon,
  ChevronDownIcon,
} from '@heroicons/react/solid';
import { User } from '../../app/models/user';

interface Props {
  onMenuButtonClick: (value: boolean) => void;
  user: User | null;
  className?: string;
  sidebarExpanded?: boolean;
}
export default function AppPageHeader({
  user,
  className,
  sidebarExpanded = false,
  onMenuButtonClick,
}: Props) {
  return (
    <div
      className={`flex flex-row justify-between items-center w-full px-5 ${className}`}
    >
      <div className='relative z-10'>
        {!sidebarExpanded && (
          <button
            type='button'
            className='p-2'
            onClick={() => onMenuButtonClick(true)}
          >
            <MenuAlt1Icon
              className={` h-6 w-6 ${
                sidebarExpanded ? 'text-white' : ' text-black'
              }`}
            />
          </button>
        )}
      </div>

      <div className=' flex flex-row gap-x-5'>
        <div className='grid grid-cols-2'>
          <button type='button' className='p-2'>
            <SearchIcon className='h-6 w-6' />
          </button>
          <button type='button' className='p-2'>
            <BellIcon className='h-6 w-6' />
          </button>
        </div>

        {user && (
          <div className='flex flex-row items-center'>
            <UserIcon className='h-6 w-6 mr-2' />
            <div className=' inline-flex'>
              <span className=' font-Secondary hidden md:block'>
                {user.username}
              </span>
              <ChevronDownIcon className='h-6 w-6 ml-2' />
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
